//! `.PKGINFO`: what a package says about itself.
//!
//! The member every apk package carries in its control segment, and the
//! grammar is one line of `key = value` with exactly one space either side of
//! the equals, `#` starting a comment, and a key that may repeat:
//!
//! ```text
//! # Generated by abuild 3.16.0-r0
//! pkgname = busybox
//! pkgver = 1.37.0-r30
//! depend = so:libc.musl-x86_64.so.1
//! datahash = 8a1172c8f10857b57e77e80850cb85fadfc7f58b25b8db3ec1a7e9693c2abd8d
//! ```
//!
//! # Why this and not the index
//!
//! Every field an installed-database record carries is published twice: here,
//! and in the index record the repository derives from here. The two agree —
//! the installed record `apk` writes is its index record verbatim — so either
//! could be the source, and this one is chosen for two reasons.
//!
//! It is complete: `replaces`, `replaces_priority` and `triggers` are stated
//! here and appear in no index, and a root that did not carry them would
//! resolve later file collisions differently from the one `apk` builds.
//!
//! And it is available in both of the layer's modes. A bootstrap from a
//! [`Plan`](super::Plan) fetches no index at all, so a record built from one
//! could not be written at all; built from here, the two modes produce the same
//! root, which is what a plan exists to promise.
//!
//! The one field that is not here is the architecture. A package built for
//! every architecture says `arch = noarch`, while the index it is published in
//! records the architecture of the repository — for the two the tests read,
//! every one of 6,264 records does — and that is what `apk` writes. So the
//! architecture comes from the resolution rather than from here, and
//! [`PkgInfo::architecture`] is what it is checked against.

use std::collections::HashMap;

use super::AlpineError;
use super::index::{Dependency, NOARCH};
use crate::provision::digest::Algorithm;

/// The separator between a key and its value: one space either side, which is
/// what `abuild` writes and what `apk` splits on.
const SEPARATOR: &str = " = ";

/// A package's own account of itself, as much of it as a bootstrap uses.
///
/// The fields are grouped by what reads them: the first block identifies the
/// package, the second becomes an installed-database record, and the third
/// drives the install.
#[derive(Debug, Clone)]
pub(super) struct PkgInfo {
    /// `pkgname`.
    pub(super) name: String,
    /// `pkgver`.
    pub(super) version: String,
    /// `arch`, which is [`NOARCH`] for a package built for every one.
    pub(super) architecture: String,

    /// `pkgdesc`, the record's `T:`.
    pub(super) description: Option<String>,
    /// `url`, the record's `U:`.
    pub(super) url: Option<String>,
    /// `license`, the record's `L:`.
    pub(super) license: Option<String>,
    /// `size`, the record's `I:`: the repository's estimate of the space the
    /// package occupies once installed, in bytes.
    pub(super) installed_size: Option<u64>,
    /// `origin`, the record's `o:`.
    pub(super) origin: Option<String>,
    /// `maintainer`, the record's `m:`.
    pub(super) maintainer: Option<String>,
    /// `builddate`, the record's `t:`.
    pub(super) build_time: Option<u64>,
    /// `commit`, the record's `c:`.
    pub(super) commit: Option<String>,
    /// `provider_priority`, the record's `k:`.
    pub(super) provider_priority: Option<u32>,
    /// `depend`, accumulated in order, the record's `D:`.
    pub(super) depends: Vec<String>,
    /// `provides`, accumulated in order, the record's `p:`.
    pub(super) provides: Vec<String>,
    /// `install_if`, accumulated in order, the record's `i:`.
    pub(super) install_if: Vec<String>,

    /// `replaces`, the record's `r:`: the packages whose files this one may
    /// overwrite.
    pub(super) replaces: Vec<Dependency>,
    /// `replaces_priority`, the record's `q:`: which of two packages that
    /// replace each other's files wins.
    pub(super) replaces_priority: Option<u32>,
    /// `triggers`: the path patterns whose contents changing runs this
    /// package's `.trigger` script.
    pub(super) triggers: Vec<String>,
    /// `datahash`: the SHA-256 of the package's *compressed* data segment,
    /// lowercase hex, which binds the file tree to the control segment the
    /// signature covers.
    pub(super) datahash: Option<String>,
}

impl PkgInfo {
    /// Whether this package belongs to every architecture.
    pub(super) fn is_noarch(&self) -> bool {
        self.architecture == NOARCH
    }

    /// Reads a package's `.PKGINFO`.
    ///
    /// `subject` names the package being read, for the errors.
    ///
    /// # Errors
    ///
    /// Returns [`AlpineError::Container`] where the member is not UTF-8, where
    /// it names no package or version, or where a field this reader
    /// understands does not hold what the format says it holds. A key it does
    /// not understand is skipped: `abuild` adds fields, and a package carrying
    /// a new one is still a package this layer installs.
    pub(super) fn parse(subject: &str, member: &[u8]) -> Result<PkgInfo, AlpineError> {
        let malformed =
            |reason: String| AlpineError::container(subject, format!(".PKGINFO {reason}"));
        let text =
            std::str::from_utf8(member).map_err(|err| malformed(format!("is not UTF-8: {err}")))?;

        let mut single: HashMap<&str, &str> = HashMap::new();
        let mut depends = Vec::new();
        let mut provides = Vec::new();
        let mut install_if = Vec::new();
        let mut replaces = Vec::new();
        let mut triggers = Vec::new();
        for line in text.lines() {
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            // A line that is not a field is skipped rather than refused, which
            // is what apk does: the member is generated, and refusing an
            // unfamiliar shape would refuse a package apk installs.
            let Some((key, value)) = line.split_once(SEPARATOR) else {
                continue;
            };
            match key {
                // The list-valued keys, which accumulate in the order the file
                // states them because that order is the one the index and the
                // installed record both carry.
                "depend" => depends.push(value.to_string()),
                "provides" => provides.push(value.to_string()),
                "install_if" => install_if.push(value.to_string()),
                "triggers" => triggers.extend(
                    value
                        .split_ascii_whitespace()
                        .map(std::string::ToString::to_string),
                ),
                "replaces" => {
                    for entry in value.split_ascii_whitespace() {
                        replaces.push(
                            Dependency::parse(entry)
                                .map_err(|reason| malformed(format!("replaces {reason}")))?,
                        );
                    }
                }
                // Everything else is single-valued. A key stated twice keeps
                // the last, which is how apk's own field table behaves.
                _ => {
                    single.insert(key, value);
                }
            }
        }

        let required = |key: &str| {
            single
                .get(key)
                .copied()
                .filter(|value| !value.is_empty())
                .ok_or_else(|| malformed(format!("states no {key}")))
        };
        let optional = |key: &str| {
            single
                .get(key)
                .copied()
                .filter(|value| !value.is_empty())
                .map(std::string::ToString::to_string)
        };

        // Held to the shape here rather than compared leniently where it is
        // used. `abuild` writes lowercase hex and the digest recomputed over the
        // data segment is lowercase hex, so a value spelled any other way is
        // malformed — and saying so is a better answer than the digest mismatch
        // an equal value spelled differently would otherwise be reported as.
        let datahash = optional("datahash");
        if let Some(datahash) = &datahash
            && !Algorithm::Sha256.is_hex(datahash)
        {
            return Err(malformed(format!(
                "states a datahash of {datahash:?}, which is not a SHA-256 in lowercase hex",
            )));
        }

        Ok(PkgInfo {
            name: required("pkgname")?.to_string(),
            version: required("pkgver")?.to_string(),
            architecture: required("arch")?.to_string(),
            description: optional("pkgdesc"),
            url: optional("url"),
            license: optional("license"),
            installed_size: count(subject, &single, "size")?,
            origin: optional("origin"),
            maintainer: optional("maintainer"),
            build_time: count(subject, &single, "builddate")?,
            commit: optional("commit"),
            provider_priority: count(subject, &single, "provider_priority")?,
            depends,
            provides,
            install_if,
            replaces,
            replaces_priority: count(subject, &single, "replaces_priority")?,
            triggers,
            datahash,
        })
    }
}

/// Reads a field that states a count, `None` where the member states none.
///
/// A free function rather than a closure beside the two above it because the
/// two callers want different widths, and a closure is monomorphized at its
/// first use.
fn count<T: std::str::FromStr>(
    subject: &str,
    fields: &HashMap<&str, &str>,
    key: &str,
) -> Result<Option<T>, AlpineError> {
    match fields.get(key).copied().filter(|value| !value.is_empty()) {
        None => Ok(None),
        Some(value) => value.parse().map(Some).map_err(|_| {
            AlpineError::container(
                subject,
                format!(".PKGINFO states {key} = {value:?}, which is not a count"),
            )
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::super::apk::{self, Segments};
    use super::super::{KeySet, fixtures};
    use super::*;

    /// The `.PKGINFO` of a committed fixture.
    fn of(container: &[u8]) -> PkgInfo {
        let mut segments = Segments::new(container);
        let metadata = apk::read_metadata(
            "the fixture",
            &mut segments,
            apk::Anchor::Signature(&KeySet::alpine("x86_64").expect("x86_64 is in the bundle")),
            16 * 1024 * 1024,
        )
        .expect("the fixture verifies");
        PkgInfo::parse(
            "the fixture",
            &metadata.member(".PKGINFO").expect("a package has one").data,
        )
        .expect("the member parses")
    }

    #[test]
    fn a_published_package_states_itself() {
        let musl = of(fixtures::MUSL);
        assert_eq!(musl.name, "musl");
        assert_eq!(musl.version, "1.2.5-r23");
        assert_eq!(musl.architecture, "x86_64");
        assert!(!musl.is_noarch());
        assert_eq!(musl.installed_size, Some(666_216));
        assert_eq!(musl.origin.as_deref(), Some("musl"));
        assert_eq!(musl.license.as_deref(), Some("MIT"));
        assert_eq!(musl.provides, ["so:libc.musl-x86_64.so.1=1"]);
        assert!(musl.depends.is_empty());
        assert_eq!(
            musl.datahash.as_deref().map(str::len),
            Some(64),
            "a SHA-256 in hex",
        );
    }

    #[test]
    fn a_repeated_key_accumulates_in_the_order_it_was_stated() {
        // `depend` is stated once per dependency, and the order is the one the
        // index publishes and the installed record carries, so it is kept
        // rather than sorted.
        let base = of(fixtures::ALPINE_BASE);
        assert_eq!(base.name, "alpine-base");
        assert!(base.is_noarch(), "a meta package belongs to every one");
        assert_eq!(
            base.depends.first().map(String::as_str),
            Some("alpine-baselayout"),
        );
        assert!(base.depends.contains(&"busybox".to_string()));
        assert_eq!(base.installed_size, Some(0), "a meta package ships nothing");

        // And the order is the file's, not one this reader imposes: an index
        // publishes `D:` in the order `.PKGINFO` states it, and an installed
        // record carries that order too.
        let stated = PkgInfo::parse(
            "the package",
            b"pkgname = a\npkgver = 1-r0\narch = noarch\n\
              depend = zlib\ndepend = musl\ndepend = busybox\n",
        )
        .expect("the member parses");
        assert_eq!(stated.depends, ["zlib", "musl", "busybox"]);
    }

    #[test]
    fn replaces_is_read_through_the_dependency_grammar() {
        // A `replaces` entry may carry a version, so it is the same grammar a
        // dependency is: reading it as a bare name would silently widen it.
        let info = PkgInfo::parse(
            "the package",
            b"pkgname = a\npkgver = 1-r0\narch = noarch\n\
              replaces = b c<2.0 d=1.0-r0\nreplaces_priority = 1000\n",
        )
        .expect("the member parses");
        assert_eq!(info.replaces.len(), 3);
        assert_eq!(info.replaces[0].name, "b");
        assert!(info.replaces[0].constraint.is_none());
        assert_eq!(info.replaces[1].name, "c");
        assert!(info.replaces[1].constraint.is_some());
        assert_eq!(info.replaces_priority, Some(1000));
    }

    #[test]
    fn triggers_are_the_whitespace_separated_patterns() {
        let info = PkgInfo::parse(
            "the package",
            b"pkgname = a\npkgver = 1-r0\narch = noarch\n\
              triggers = /bin /usr/bin /lib/modules/*\n",
        )
        .expect("the member parses");
        assert_eq!(info.triggers, ["/bin", "/usr/bin", "/lib/modules/*"]);
    }

    #[test]
    fn a_comment_and_an_unknown_key_are_skipped() {
        let info = PkgInfo::parse(
            "the package",
            b"# Generated by abuild\npkgname = a\npkgver = 1-r0\narch = noarch\n\
              packager = Someone\nsomething-new = whatever\n",
        )
        .expect("the member parses");
        assert_eq!(info.name, "a");
        // `packager` is one apk itself drops, and a key a later abuild adds is
        // no different: a package carrying one is still installable.
        assert!(info.description.is_none());
    }

    #[test]
    fn a_member_naming_no_package_is_refused() {
        for member in [
            &b"pkgver = 1-r0\narch = noarch\n"[..],
            &b"pkgname = a\narch = noarch\n"[..],
            &b"pkgname = a\npkgver = 1-r0\n"[..],
            &b"pkgname = \npkgver = 1-r0\narch = noarch\n"[..],
        ] {
            let err = PkgInfo::parse("the package", member)
                .expect_err("a package states its name, version and architecture");
            assert!(matches!(err, AlpineError::Container { .. }), "{err}");
        }
    }

    #[test]
    fn a_count_that_is_not_one_is_refused() {
        let err = PkgInfo::parse(
            "the package",
            b"pkgname = a\npkgver = 1-r0\narch = noarch\nsize = enormous\n",
        )
        .expect_err("a size is a count");
        assert!(
            matches!(&err, AlpineError::Container { reason, .. } if reason.contains("size")),
            "{err}",
        );
    }
}
